const $=s=>document.querySelector(s);
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const paths={arrow:'M4 10h12m-5-5 5 5-5 5',diagonal:'M5 15 15 5M5 5h10v10',moon:'M16.5 12.5A7 7 0 0 1 7.5 3.5a7 7 0 1 0 9 9Z',sun:'M10 1v2m0 14v2M1 10h2m14 0h2M3 3l2 2m10 10 2 2M3 17l2-2M15 5l2-2',menu:'M3 5h14M3 10h14M3 15h14',close:'m4 4 12 12M4 16 16 4',briefcase:'M6 6V3h8v3M2 11c5 3 11 3 16 0M10 10v4',people:'M2 18v-3a6 6 0 0 1 12 0v3M14 3a3 3 0 0 1 0 6m2 3a5 5 0 0 1 2 6',grid:'M3 3h5v5H3zM12 3h5v5h-5zM3 12h5v5H3zM12 12h5v5h-5z',file:'M5 2h7l4 4v12H5zM12 2v5h4M8 11h5M8 14h5',bookmark:'M5 3h10v14l-5-3-5 3Z',upload:'M10 13V2M6 6l4-4 4 4M3 12v5h14v-5',check:'m4 10 4 4 8-8',calendar:'M3 5h14v13H3zM3 9h14M6 2v5m8-5v5',bell:'M5 8a5 5 0 0 1 10 0v5l2 2H3l2-2ZM8 18h4',search:'m14 14 4 4',location:'M10 18S3 11 3 7a7 7 0 0 1 14 0c0 4-7 11-7 11Z',clock:'M10 5v5l3 2',settings:'m8 2-.7 2-2 .8-2-.7-1.5 2 1.4 1.7-.1 2.2L1.5 12l1 2.2 2.2-.2 1.7 1.3.3 2.2h2.6l.8-2 2-.8 2 .7 1.5-2-1.4-1.7.1-2.2 1.6-2-1-2.2-2.2.2L13 4.2 12.7 2Z',logout:'M8 3H3v14h5m4-12 5 5-5 5M7 10h10',plus:'M10 3v14M3 10h14',mail:'M2 4h16v12H2zM2 4l8 7 8-7',spark:'m10 2 2.4 5.6L18 10l-5.6 2.4L10 18l-2.4-5.6L2 10l5.6-2.4Z',activity:'M2 10h4l2-6 4 12 2-6h4',shield:'M10 2 3 5v5c0 4 7 8 7 8s7-4 7-8V5Z',download:'M10 2v11M6 9l4 4 4-4M3 15v3h14v-3',heart:'M10 17 3 10C-1 5 6 0 10 6c4-6 11-1 7 4Z',globe:'M2 10h16M10 2c-5 5-5 11 0 16M10 2c5 5 5 11 0 16'};
const icon=name=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true">${name==='sun'?'<circle cx="10" cy="10" r="3.5"/>':''}${name==='briefcase'?'<rect x="2" y="6" width="16" height="12" rx="2"/>':''}${name==='people'?'<circle cx="8" cy="6" r="3"/>':''}${name==='search'?'<circle cx="8.5" cy="8.5" r="5.5"/>':''}${['clock','globe'].includes(name)?'<circle cx="10" cy="10" r="8"/>':''}${name==='location'?'<circle cx="10" cy="7" r="2"/>':''}${name==='settings'?'<circle cx="9" cy="10" r="2.5"/>':''}<path d="${paths[name]||paths.arrow}"/></svg>`;
const state={user:null,config:{},saved:new Set(),notifications:[],data:{},view:'table'};
let mode='light';try{mode=localStorage.getItem('blackstone-platform-theme')||'light'}catch{}document.documentElement.dataset.theme=mode;
const countryOptions=()=>state.config.countries.map(c=>[c.value,c.label]);
const countryName=value=>state.config.countries?.find(c=>c.value===value)?.label||value;
const stages=['Applied','Reviewing','Shortlisted','Interview','Offer','Hired','Declined','Withdrawn'];
const initials=name=>String(name||'B').split(' ').map(x=>x[0]).slice(0,2).join('');
const date=(value,options={dateStyle:'medium'})=>new Intl.DateTimeFormat('en-GB',options).format(new Date(value));
const money=j=>`${j.currency} ${Number(j.salary_min).toLocaleString('en-GB')} – ${Number(j.salary_max).toLocaleString('en-GB')}`;
const avatar=name=>`<span class="avatar">${e(initials(name))}</span>`;
const statusBadge=s=>`<span class="tag dot ${['Hired','Shortlisted','published','Completed'].includes(s)?'green':['Declined','Withdrawn','Cancelled','closed'].includes(s)?'red':['Interview','Reviewing'].includes(s)?'blue':'gold'}">${e(s)}</span>`;
const brand=()=>`<a class="brand" href="/" aria-label="Blackstone UK Recruitment home"><span class="brand-emblem" aria-hidden="true"><img src="/assets/client-brand-reference.jpeg" alt=""></span><span class="brand-lockup"><span class="brand-name">Blackstone</span><span class="brand-descriptor">UK Recruitment</span></span></a>`;
const contactEmail=()=>state.config.contactEmail||'info@bsukrecruitment.com';
const contactLink=()=>`<a href="mailto:${e(contactEmail())}">${e(contactEmail())}</a>`;
const isStaff=()=>state.user&&state.user.role!=='candidate';
const isEmployer=()=>state.user?.role==='employer';
const base=()=>isEmployer()?'/employer':isStaff()?'/workspace':'/dashboard';
async function api(endpoint,options={}){if(isEmployer()){if(endpoint.startsWith('/staff/jobs'))endpoint=endpoint.replace('/staff/jobs','/employer/jobs');else if(/^\/(applications|interviews)(?:\/|$)/.test(endpoint))endpoint='/employer'+endpoint;}const headers={'X-Blackstone-Request':'1',...options.headers};let body=options.body;if(body&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body)}const response=await fetch('/api'+endpoint,{...options,headers,body,credentials:'same-origin'});const result=await response.json().catch(()=>({error:'The server returned an unexpected response.'}));if(!response.ok){const error=new Error(result.error||'Please try again.');error.status=response.status;throw error}return result}
let toastTimeout;function toast(message,error=false){$('#toast').textContent=message;$('#toast').className=`show${error?' error':''}`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').className='',4500)}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`}
function selectField(label,name,options,value='',extra=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(value)===String(v)?'selected':''}>${e(t)}</option>`}).join('')}</select></div>`}
const empty=(heading,description,href='',label='Explore opportunities')=>`<div class="empty-state">${icon('briefcase')}<h3>${heading}</h3><p>${description}</p>${href?`<a class="btn outline" href="${href}">${label} ${icon('arrow')}</a>`:''}</div>`;
const heading=(small,title,description,actions='')=>`<div class="dashboard-heading"><div><div class="eyebrow">${small}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;
const luxuryEditorial=()=>`<figure class="luxury-editorial"><img src="/assets/executive-lounge.png" alt="An elegant cream and walnut executive lounge with city views" width="1672" height="941" loading="lazy"><figcaption>A new perspective. A world of possibility.</figcaption></figure>`;
function publicShell(content){return `<div class="public"><div class="watermark" aria-hidden="true">BLACKSTONE</div><header class="container"><div class="top-strip"><span>A higher standard of connection</span><span>Worldwide opportunities <span>•</span> Personal connections</span></div><div class="public-nav">${brand()}<nav class="nav-links" aria-label="Main navigation"><a href="/about">About us</a><a href="/contact">Contact us</a><a class="${location.pathname.startsWith('/jobs')?'active':''}" href="/jobs">Find a role</a><a href="/employers">For employers</a><a href="/middle-east-healthcare">Middle East Healthcare</a><a href="/approach">Our approach</a><a class="mobile-account-link" href="${state.user?base():'/login'}">${state.user?'My workspace':'Sign in'}</a><a class="mobile-account-link" href="${state.user?base():'/register'}">${state.user?'Go to dashboard':'Create an account'}</a></nav><div class="nav-actions"><button class="icon-button" data-action="theme" aria-label="Switch to ${mode==='light'?'dark':'light'} mode">${icon(mode==='light'?'moon':'sun')}</button><a class="signin-link" href="${state.user?base():'/login'}">${state.user?'My workspace':'Sign in'}</a><a class="btn small" href="${isStaff()?base():state.user?'/dashboard/cv':'/register?next=%2Fdashboard%2Fcv'}">${isStaff()?'Workspace':'Submit your CV'} ${icon('diagonal')}</a><button class="icon-button menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button></div></div></header><main id="content" tabindex="-1" class="route-in">${content}</main><footer class="container"><div class="footer-main">${brand()}<div class="footer-links"><a href="/jobs">Find your next role</a><a href="/employers">Find your next hire</a><a href="/middle-east-healthcare">Middle East Healthcare</a><a href="/approach">Our approach</a><a href="/about">About us</a><a href="/contact">Contact us</a><a href="/companies">Explore companies</a><a href="/privacy">Privacy & data</a><a href="/login?next=%2Femployer">Employer sign in</a>${contactLink()}<a href="tel:+448000437867">+44 800 043 7867</a></div></div><div class="footer-company"><span>Blackstone UK Recruitment Ltd</span><span>Company number: 17203133</span><span>9 Prescott Street, Bolton, BL3 3LZ</span><a href="/privacy">ICO registration: ZC256765</a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Blackstone UK Recruitment. All rights reserved.</span><span>Talent without borders</span></div></footer></div>`}
function workspaceShell(content,title){const staff=isStaff();const entries=isEmployer()?[['','grid','Company overview'],['/company','briefcase','Company profile'],['/jobs','briefcase','My jobs'],['/applications','people','Applicants'],['/interviews','calendar','Interviews']]:staff?[['','grid','Overview'],['/applications','people','Applications'],['/talent','people','Talent pool'],['/jobs','briefcase','Job board'],['/interviews','calendar','Interviews'],['/enquiries','mail','Hiring enquiries']]:[['','grid','Overview'],['/applications','file','My applications'],['/matches','spark','Suggested jobs'],['/saved','bookmark','Saved roles'],['/cv','upload','My CV library'],['/interviews','calendar','Interviews']];const settings=staff?[...(state.user.role==='admin'?[['/companies','briefcase','Companies'],['/team','people','Team & access'],['/activity','activity','Activity log']]:[]),['/profile','settings','My account']]:[['/profile','people','My profile'],['/notifications','bell','Notifications']];return `<div class="workspace"><div class="watermark" aria-hidden="true">BLACKSTONE</div><aside class="sidebar" aria-label="Workspace navigation"><button class="mobile-sidebar-close" data-action="sidebar" aria-label="Close workspace navigation">×</button>${brand()}<div class="sidebar-group">${isEmployer()?'COMPANY WORKSPACE':staff?'RECRUITMENT WORKSPACE':'YOUR NEXT CHAPTER'}</div><nav class="side-nav">${entries.map(([path,i,label])=>`<a href="${base()+path}" class="${location.pathname===base()+path||(path==='/applications'&&location.pathname.startsWith(base()+path+'/'))?'active':''}">${icon(i)}${label}</a>`).join('')}</nav><div class="sidebar-group">${staff?'MANAGE':'PERSONAL'}</div><nav class="side-nav">${settings.map(([path,i,label])=>`<a href="${base()+path}" class="${location.pathname===base()+path?'active':''}">${icon(i)}${label}</a>`).join('')}</nav><div class="sidebar-end"><div class="sidebar-account">${avatar(state.user.name)}<span><strong>${e(state.user.name)}</strong><small>${staff?isEmployer()?'Employer':state.user.role==='admin'?'Administrator':'Recruiter':'Candidate'}</small></span><button data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><button class="sidebar-backdrop" data-action="sidebar" aria-label="Dismiss workspace menu" tabindex="-1"></button><div class="workspace-main"><header class="workspace-topbar"><div class="breadcrumb"><button class="icon-button menu-toggle" data-action="sidebar" aria-label="Open workspace navigation" aria-expanded="false">${icon('menu')}</button><span>${staff?'Workspace':'My account'}</span><span>/</span><strong>${e(title)}</strong></div><div class="topbar-actions"><a href="/">View website ${icon('diagonal')}</a><button class="icon-button" data-action="theme" aria-label="Switch to ${mode==='light'?'dark':'light'} mode">${icon(mode==='light'?'moon':'sun')}</button><a class="icon-button" href="${base()}/notifications" aria-label="Notifications">${icon('bell')}${state.notifications.some(n=>!n.read)?`<span class="badge-count">${state.notifications.filter(n=>!n.read).length}</span>`:''}</a>${avatar(state.user.name)}</div></header><main id="content" class="workspace-content route-in" tabindex="-1">${content}${state.config.demo?'<p class="demo-label">LOCAL DEMONSTRATION · Seeded people and vacancies are fictional. New actions are saved to this development database.</p>':''}</main></div></div>`}
function jobCard(j){return `<article class="job-card"><div class="job-card-top"><span class="tag gold">${e(j.sector)}</span>${!isStaff()?`<button class="save-btn ${state.saved.has(j.id)?'saved':''}" data-action="save" data-id="${j.id}" aria-label="${state.saved.has(j.id)?'Unsave':'Save'} ${e(j.title)}" aria-pressed="${state.saved.has(j.id)}">${icon('bookmark')}</button>`:''}</div><p class="job-company">${j.company_id?`<a href="/companies/${j.company_id}">${e(j.company)}</a>`:e(j.company)}</p><h3><a href="/jobs/${j.id}">${e(j.title)}</a></h3><p>${e(j.location)}, ${e(j.country)} &nbsp; · &nbsp; ${e(j.workplace)}</p><div class="job-card-foot"><span><strong>${money(j)}</strong><br><small>per ${e(j.period)} · ${e(j.type)}</small></span><a class="icon-button" href="/jobs/${j.id}" aria-label="View ${e(j.title)}">${icon('diagonal')}</a></div></article>`}
function quickContactCard(){const hiring=isStaff(),primary=hiring?base()+'/jobs/new':'/jobs',secondary=hiring?base()+'/applications':state.user?'/dashboard/cv':'/register?next=%2Fdashboard%2Fcv';return `<section class="quick-contact" aria-labelledby="quick-contact-title"><div class="quick-contact-main"><div class="eyebrow">A personal connection</div><h2 id="quick-contact-title">Your next chapter.<br><em>One conversation away.</em></h2><p>Looking for a role or the right people? Let’s talk.</p><div class="quick-contact-methods"><a href="tel:+448000437867"><span>Call our team</span><strong>+44 800 043 7867</strong>${icon('diagonal')}</a><a href="mailto:info@bsukrecruitment.com"><span>Email us</span><strong>info@bsukrecruitment.com</strong>${icon('diagonal')}</a></div><a class="text-link" href="/contact">Contact details & operating hours ${icon('arrow')}</a></div><aside class="quick-contact-action"><span class="quick-contact-mark" aria-hidden="true">${icon(hiring?'briefcase':'people')}</span><h3>${hiring?'Build an exceptional team.':'Find your next opportunity.'}</h3><p>${hiring?'Publish a role and manage the conversations that follow.':'Explore current roles or add your CV to your candidate account.'}</p><a class="btn" href="${primary}">${hiring?'Post a job':'Search jobs'} ${icon('arrow')}</a><a class="btn outline" href="${secondary}">${hiring?'Manage applications':state.user?'My CV library':'Register your CV'}</a>${!hiring?'<a class="quick-contact-employer" href="/employers">Hiring for your company? '+icon('diagonal')+'</a>':''}</aside></section>`;}
async function homePage(){const {jobs}=await api('/jobs');return publicShell(`<div class="container"><section class="hero"><div class="hero-layout"><div class="hero-copy"><div class="eyebrow">Worldwide opportunities.</div><h1>Where ambition<br>finds its<br><em>next chapter.</em></h1><p>International recruitment, with a dedicated focus on healthcare across Saudi Arabia and the Middle East.</p><form class="hero-search" data-form="job-search"><label for="home-search">Your next opportunity</label><div><input id="home-search" name="q" type="search" placeholder="Job title, skill or company"><button class="btn" type="submit">Search jobs ${icon('arrow')}</button></div></form><div class="hero-actions"><a class="btn" href="/jobs">Discover opportunities ${icon('diagonal')}</a><a class="text-link" href="/employer/register">Post a job ${icon('arrow')}</a></div></div><div class="hero-image"><img src="/assets/architecture-luminous.png" alt="Sunlit ivory architecture and champagne bronze details framing a contemporary glass tower" width="1122" height="1402" fetchpriority="high"><div class="image-corner"></div><div class="hero-seal">B<small>GO FURTHER</small></div><div class="image-caption"><small>A DIFFERENT PERSPECTIVE ON RECRUITMENT</small><strong>Built on people.<br>Defined by possibility.</strong></div></div></div></section><div class="market-bar"><span>GLOBAL PERSPECTIVE.<br>PERSONAL ATTENTION.</span><a href="/jobs"><span class="market-code">01</span><strong>Opportunities worldwide</strong><small>Find your next chapter</small></a><a href="/employers"><span class="market-code">02</span><strong>Exceptional talent</strong><small>Build your next team</small></a><a href="/approach"><span class="market-code">03</span><strong>A human connection</strong><small>Discover our approach</small></a></div><section class="healthcare-panel" aria-labelledby="healthcare-heading"><div class="healthcare-intro"><div class="eyebrow">Middle East Healthcare</div><h2 id="healthcare-heading">Specialist healthcare recruitment for Saudi Arabia and the wider Middle East</h2><p class="healthcare-signature">Local understanding. International reach.<br>Exceptional healthcare talent.</p></div><div class="healthcare-details"><p>Blackstone UK Recruitment connects hospitals, clinics and specialist healthcare organisations across the Middle East with carefully selected UK and international medical professionals.</p><p>From experienced doctors and nurses to allied health professionals and senior clinical specialists, we provide a personal, carefully managed recruitment service shaped around each organisation’s requirements.</p><div class="healthcare-actions"><a class="btn" href="/healthcare-enquiry">Discuss your staffing requirements ${icon('arrow')}</a><a class="btn outline" href="/jobs?sector=Healthcare">Explore Healthcare Opportunities ${icon('diagonal')}</a></div></div><p class="healthcare-footnote">Dedicated recruitment support for Saudi Arabia and the GCC <a class="text-link" href="/middle-east-healthcare">Discover our healthcare expertise ${icon('arrow')}</a></p></section><section class="section"><div class="section-head"><div><div class="eyebrow">A considered next move</div><h2>Good things are ahead.</h2></div><a class="text-link" href="/jobs">Explore all opportunities ${icon('arrow')}</a></div><div class="job-grid">${jobs.length?jobs.slice(0,3).map(jobCard).join(''):empty(isStaff()?'Your next hire starts here.':'Your next chapter is taking shape.',isStaff()?'Publish an opportunity to start receiving applications.':'Join our talent community so the team can get to know you.',isStaff()?base()+'/jobs/new':state.user?'/dashboard/profile':'/register',isStaff()?'Post a job':state.user?'Complete your profile':'Create your profile')}</div>${state.config.demo?'<p class="demo-label">Illustrative vacancies in the local demonstration workspace.</p>':''}</section>${luxuryEditorial()}<section class="dark-panel philosophy"><div><div class="eyebrow">The Blackstone difference</div><h2>More than a placement.<br>A meaningful connection.</h2><p>Behind every CV is a story. Behind every business is an ambition. Our work is bringing the right ones together.</p><a class="btn gold" href="/approach">Get to know Blackstone ${icon('diagonal')}</a></div><div class="steps"><div class="step"><small>01 / DISCOVER</small><h3>Find a role that fits.</h3><p>Search opportunities and explore the companies behind them.</p></div><div class="step"><small>02 / APPLY</small><h3>Apply with confidence.</h3><p>Choose your CV and send your introduction directly to the hiring team.</p></div><div class="step"><small>03 / BUILD</small><h3>Stay in the conversation.</h3><p>Track updates, exchange messages and prepare for interviews.</p></div></div></section>${quickContactCard()}</div>`)}
async function jobsPage(){const {jobs}=await api('/jobs');state.data.jobs=jobs;const params=new URLSearchParams(location.search);return publicShell(`<div class="container page-body"><div class="page-head"><div class="eyebrow">Find your next chapter</div><h1>Ambition looks good on you.</h1><p>Explore opportunities around the world. Find the role, the people and the place where you can thrive.</p></div><div class="filters"><div class="field"><label for="job-search">Your next role</label><input id="job-search" type="search" placeholder="Job title, skill or keyword" value="${e(params.get('q')||'')}"></div>${selectField('Country / territory','job-country',[['','All countries & territories'],...countryOptions()],params.get('country')||'')}${selectField('Specialism','job-sector',[['','All specialisms'],...new Set(['Healthcare',...jobs.map(j=>j.sector)])],params.get('sector')||'')}${selectField('Workplace','job-workplace',[['','All workplaces'],'Hybrid','On-site','Remote'],params.get('workplace')||'')}</div><div class="result-bar"><span id="job-count" aria-live="polite"></span><a class="mini-link" href="/companies">Explore companies</a><button class="mini-link reset-filters" data-action="reset-filters">Clear filters</button></div><div id="jobs-results" class="job-grid"></div>${state.config.demo?'<p class="demo-label">These vacancies are sample data for the local development workspace.</p>':''}<div class="cta-band"><div><h2>${isStaff()?'Find your next hire.':'Not quite your next move?'}</h2><p>${isStaff()?'Manage opportunities and connect with candidates.':'Create a profile and introduce yourself to our recruitment team.'}</p></div><a class="btn outline" href="${isEmployer()?'/employer/jobs/new':isStaff()?'/workspace/talent':state.user?'/dashboard/profile':'/register?next=%2Fdashboard%2Fprofile'}">${isEmployer()?'Post a job':isStaff()?'View talent community':'Join our talent community'} ${icon('arrow')}</a></div></div>`)}
function filterJobs(){const q=$('#job-search').value.trim().toLowerCase(),country=$('#job-country').value,sector=$('#job-sector').value,work=$('#job-workplace').value;const params=new URLSearchParams();for(const [key,value] of [['q',$('#job-search').value.trim()],['country',country],['sector',sector],['workplace',work]])if(value)params.set(key,value);const query=params.toString();state.jobsSearch=query?'?'+query:'';history.replaceState(history.state,'','/jobs'+state.jobsSearch);currentPageUrl=location.pathname+location.search;$('.reset-filters').disabled=!query;const jobs=state.data.jobs.filter(j=>(!q||`${j.title} ${j.company} ${j.location} ${countryName(j.country)} ${j.requirements}`.toLowerCase().includes(q))&&(!country||j.country===country)&&(!sector||j.sector===sector)&&(!work||j.workplace===work));$('#job-count').textContent=`${jobs.length} ${jobs.length===1?'opportunity':'opportunities'} to explore`;$('#jobs-results').innerHTML=jobs.length?jobs.map(jobCard).join(''):sector==='Healthcare'&&!state.data.jobs.some(j=>j.sector==='Healthcare')?empty('Healthcare opportunities are on the horizon.',isStaff()?'Publish a healthcare role to connect with professionals.':'There are no healthcare vacancies currently advertised. Create your profile and choose to share your interest with our recruitment team.',isStaff()?base()+'/jobs/new':healthcareInterestLink(),isStaff()?'Post a healthcare role':'Register your healthcare interest'):state.data.jobs.length?empty('No matches just yet.','Try a different keyword or broaden your search.'):empty('Our first opportunities are coming soon.',isStaff()?'Publish a role to start receiving applications.':'Join our talent community and introduce yourself to our recruitment team.',isEmployer()?'/employer/jobs/new':isStaff()?'/workspace/jobs/new':state.user?'/dashboard/profile':'/register?next=%2Fdashboard%2Fprofile',isStaff()?'Post a job':'Join our talent community');}
async function jobDetail(id){const {job:j}=await api('/jobs/'+id);state.data.job=j;const previous=state.user&&!isStaff()?(await api('/applications')).applications.find(a=>a.job_id===j.id):null;return publicShell(`<div class="container page-body"><div class="job-detail-hero"><a class="mini-link" href="/jobs${e(state.jobsSearch||'')}">← All opportunities</a><div style="margin-top:25px">${statusBadge(j.type)} <span class="tag gold">${e(j.sector)}</span></div><h1>${e(j.title)}</h1><div class="job-meta"><span>${icon('location')} ${e(j.location)}, ${e(j.country)}</span><span>${icon('briefcase')} ${e(j.workplace)}</span><span>${icon('clock')} Posted ${date(j.created_at)}</span></div></div><div class="two-col"><div class="panel"><h3>The opportunity</h3><p class="detail-copy">${e(j.description)}</p><h3 style="margin-top:35px">What you’ll bring</h3><ul class="detail-copy">${j.requirements.split(/[,\n]/).filter(Boolean).map(s=>`<li>${e(s.trim())}</li>`).join('')}</ul>${j.benefits?`<h3 style="margin-top:35px">What you can look forward to</h3><p class="detail-copy">${e(j.benefits)}</p>`:''}</div><aside><div class="panel"><div class="eyebrow">Your next chapter</div><h3>${money(j)}</h3><p class="fine">per ${e(j.period)}</p><div class="facts"><div><span>Location</span><strong>${e(j.location)}</strong></div><div><span>Contract</span><strong>${e(j.type)}</strong></div><div><span>Workplace</span><strong>${e(j.workplace)}</strong></div><div><span>Organisation</span><strong>${j.company_id?`<a href="/companies/${j.company_id}">${e(j.company)}</a>`:e(j.company)}</strong></div></div>${isEmployer()?`<a class="btn full" href="/employer/jobs">My company jobs ${icon('arrow')}</a>`:isStaff()?`<a class="btn full" href="/workspace/jobs/${j.id}">Manage this role ${icon('arrow')}</a>`:previous?`<div class="notice">You have already applied · ${e(previous.status)}</div><a class="btn full" href="/dashboard/applications/${previous.id}">View your application ${icon('arrow')}</a>`:`<button class="btn full" data-action="apply" data-id="${j.id}">Apply for this role ${icon('arrow')}</button>`}<button class="btn outline full" ${isStaff()?'hidden':''} style="margin-top:12px" data-action="save" data-id="${j.id}">${icon('bookmark')} ${state.saved.has(j.id)?'Remove saved role':'Save for later'}</button><p class="fine" style="margin:18px 0 0">Your application and selected CV are shared with the hiring company and authorised Blackstone recruitment staff.</p></div><div class="notice" style="margin-top:20px">A thoughtful next move starts with an honest conversation. Share your experience and what comes next for you.</div></aside></div></div>`)}
function employersPage(){const healthcare=new URLSearchParams(location.search).get('specialism')==='healthcare';return publicShell(`<div class="container page-body"><div class="page-head"><div class="eyebrow">${healthcare?'Middle East Healthcare':'For ambitious businesses'}</div><h1>${healthcare?'Your healthcare team.<br><em>Our dedicated support.</em>':'Your company.<br><em>Your next great hire.</em>'}</h1><p>${healthcare?'Tell us about your clinical hiring requirements, or create a company account to publish healthcare opportunities.':'Create your company account, publish opportunities and manage applicants from your own hiring workspace.'}</p><div class="hero-actions"><a class="btn" href="${isEmployer()?'/employer':'/employer/register'}">${isEmployer()?'Open company workspace':'Create a company account'} ${icon('arrow')}</a><a class="text-link" href="/login?next=%2Femployer">Employer sign in</a></div></div><div class="split-features"><article><small>01 / PUBLISH</small><h3>Make your role visible.</h3><p>Build your company profile, preview a job and publish when you are ready.</p></article><article><small>02 / REVIEW</small><h3>Meet your applicants.</h3><p>Review CVs, shortlist candidates and keep private hiring notes.</p></article><article><small>03 / HIRE</small><h3>Keep the conversation moving.</h3><p>Message candidates, arrange interviews and update every application through to a decision.</p></article></div><div class="two-col"><div class="dark-panel"><div class="eyebrow">GLOBAL RECRUITMENT</div><h2>Local knowledge.<br>Broader possibilities.</h2><p>Technology, finance, human resources, marketing and operations. Tell us where your business is going.</p><img src="/assets/executive-lounge.png" alt="An elegant executive lounge with warm brass and cream interiors" style="width:100%;height:220px;object-fit:cover;filter:sepia(.15);margin-top:25px;border-radius:3px" loading="lazy"></div>${hiringEnquiryForm(healthcare)}</div></div>`)}
function approachPage(){return publicShell(`<div class="container page-body"><div class="page-head"><div class="eyebrow">The Blackstone approach</div><h1>People first.<br><em>Possibilities follow.</em></h1><p>Recruitment is a human business. We bring care, clarity and a considered perspective to every connection we make.</p></div><div class="dark-panel philosophy"><h2>“A better next step<br>starts with a better<br>conversation.”</h2><div><p>We look beyond a title, a vacancy or a list of skills. We want to understand where you’ve been, where you want to go and what meaningful progress looks like to you.</p><p>Wherever your next chapter takes you, our approach stays the same: listen closely, communicate clearly and keep people at the centre.</p></div></div><div class="split-features"><article><small>01 / THOUGHTFUL</small><h3>We take the time.</h3><p>Understanding people and businesses properly is the foundation of a better introduction.</p></article><article><small>02 / TRANSPARENT</small><h3>You know where you stand.</h3><p>Track applications, manage your profile and keep your recruitment journey in one place.</p></article><article><small>03 / HUMAN</small><h3>Technology, with judgement.</h3><p>Tools can surface evidence and organise information. Our people stay responsible for every hiring decision.</p></article></div><div class="cta-band"><div><h2>Let’s find your next chapter.</h2><p>Make a connection that means something.</p></div><a href="/jobs" class="btn">Explore opportunities ${icon('arrow')}</a></div></div>`)}
function authPage(kind='login'){const register=kind==='register',forgot=kind==='forgot',reset=kind==='reset';return publicShell(`<div class="container"><div class="auth-layout"><div class="auth-story"><div class="eyebrow">YOUR AMBITION. OUR COMMITMENT.</div><div><h2>Some connections<br>change<br><em>everything.</em></h2><p>Your next chapter deserves a thoughtful beginning.</p></div><span class="fine" style="color:#c2b28f">OPPORTUNITY WITHOUT BORDERS</span></div><div class="auth-form"><div class="eyebrow">${register?'A new beginning':forgot||reset?'Account recovery':'Good to see you again'}</div><h1>${register?'Create your account.':forgot?'Let’s get you back in.':reset?'A fresh start.':'Welcome back.'}</h1><p>${register?'Create your candidate account and find your next opportunity.':forgot?(state.config.emailEnabled?'We’ll email you a secure password reset link.':'Email recovery is being activated. Contact our team for account assistance.'):reset?'Choose a new, strong password for your account.':'Sign in to continue your Blackstone journey.'}</p>${forgot&&!state.config.emailEnabled?`<div class="notice">Account support: ${contactLink()}</div>`:`<form data-form="${kind}">${register?field('Full name','name','','text','required autocomplete="name" maxlength="100"'):''}${!reset?field('Email address','email','','email','required autocomplete="email"'):''}${!forgot?field(register||reset?'Password · at least 12 characters':'Password','password','','password',`required ${register||reset?'minlength="12"':''} maxlength="128" autocomplete="${register||reset?'new-password':'current-password'}"`):''}${register?'<label class="check-label"><input type="checkbox" name="consent" required><span>I agree to the <a href="/privacy" class="mini-link">privacy notice</a> and understand my details will be used to manage my recruitment profile.</span></label>':''}${kind==='login'?'<a class="mini-link" href="/forgot">Forgot your password?</a>':''}<p class="error-inline" data-error role="alert"></p><button class="btn full" type="submit">${register?'Create my account':forgot?'Send reset link':reset?'Update password':'Sign in'} ${icon('arrow')}</button></form>`}<div class="auth-bottom">${register?'Already have an account? <a href="/login">Sign in</a>':kind==='login'?'New to Blackstone UK Recruitment? <a href="/register">Create an account</a>':'<a href="/login">Return to sign in</a>'}</div>${register?'<div class="notice">Hiring for a company? <a href="/employer/register">Create an employer account</a> to post jobs and review applicants.</div>':''}${state.config.demo&&kind==='login'?`<div class="auth-demo"><p>Local demo access · fictional accounts</p><button class="btn outline small" data-action="demo-login" data-role="recruiter">Explore recruiter workspace</button><button class="btn outline small" data-action="demo-login" data-role="candidate">Explore candidate account</button></div>`:''}</div></div></div>`)}
function privacyPage(){return publicShell(`<div class="container page-body"><div class="page-head"><div class="eyebrow">Your information, thoughtfully handled</div><h1>Privacy & your recruitment journey.</h1></div><article class="panel privacy-copy"><p class="fine">Last updated: 4 October 2026</p><section class="company-registration" id="company-details" aria-labelledby="company-details-title"><div class="eyebrow">Company & data protection</div><h2 id="company-details-title">Blackstone UK Recruitment Ltd</h2><address>9 Prescott Street<br>Bolton, BL3 3LZ<br>United Kingdom</address><dl class="registration-facts"><div><dt>Company registration number</dt><dd>17203133</dd></div><div><dt>ICO registration reference</dt><dd>ZC256765</dd></div></dl><p>Data Protection Officer: <a href="mailto:Sam@bsukrecruitment.com">Sam@bsukrecruitment.com</a></p></section><h3>Contacting us about your information</h3><p>This notice explains how the Blackstone UK Recruitment platform handles your information. For privacy questions or to exercise your data rights, email ${contactLink()} or call <a href="tel:+448000437867">+44 800 043 7867</a>.</p><h3>What this platform stores</h3><p>Your account details, company or candidate profile information, job listings, uploaded CVs, applications and interview records are stored in Blackstone’s recruitment database. Recruiter notes and application history support the hiring process. Your session uses a secure, HTTP-only cookie; your light or dark preference is saved in your browser.</p><h3>Who can access your CV</h3><p>Your files are private to your account. The hiring company can access the CV attached to an application for its own role. Authorised Blackstone recruitment staff can also access applications and their attached CVs. If you opt into the talent community, staff can also access your profile and CV library. No CV has a public download URL.</p><h3>Optional AI-assisted review</h3><p>External AI processing is optional and requires your consent in your profile settings. If enabled, relevant extracted CV text and job requirements are sent to OpenAI to help a recruiter identify evidence and follow-up questions. AI does not decide whether to hire or reject you. A local keyword checklist is available without external AI processing.</p><h3>Your choices</h3><p>You can update your profile, change AI and talent-community consent, remove unused CVs and withdraw active applications from your account. CVs already attached to an application remain part of that record. Contact ${contactLink()} for access, correction or deletion requests.</p><h3>Service providers</h3><p>The platform and its recruitment database are hosted on Render in Frankfurt, Germany. Google Fonts supplies the website typefaces. Brevo processes recipient addresses and transactional messages for password recovery and hiring-enquiry notifications. OpenAI processes relevant CV text only when AI review is enabled and you have opted in. These providers may process information in other countries under their own service arrangements.</p><h3>Keeping and removing records</h3><p>Account, CV and recruitment records remain stored until they are removed through the available account controls or by the recruitment team. Withdrawing an application does not automatically delete its history or attached CV. To request deletion or ask how long a particular record will be kept, contact ${contactLink()}. If a record needs to be retained for an ongoing recruitment process or legal obligation, the team will explain this when responding to your request.</p><h3>Questions and complaints</h3><p>Please contact us if you have concerns about your information. Depending on applicable law, you may have rights to access, correct, erase or restrict the use of your data, object to processing, and request a portable copy. You may also complain to your local data protection authority. In the UK, this is the <a href="https://ico.org.uk/make-a-complaint/" target="_blank" rel="noopener noreferrer">Information Commissioner’s Office</a>.</p>${state.config.demo?'<p class="fine">You are viewing a local demonstration. Use fictional details and sample CVs only.</p>':''}</article></div>`)}
const statCard=(label,n,sub,i,primary=false)=>`<div class="stat-card ${primary?'primary':''}"><div class="stat-top"><span>${label}</span>${icon(i)}</div><strong>${Number(n).toString().padStart(2,'0')}</strong><small>${sub}</small></div>`;
function appTable(applications,staff=true){if(!applications.length)return empty('A fresh start.',staff?'Applications will appear here when candidates apply to your roles.':'Your submitted applications and progress will appear here.',staff?base()+'/jobs':'/jobs',staff?'Manage your roles':'Explore opportunities');return `<div class="table-wrap"><table><thead><tr><th>${staff?'Candidate':'Opportunity'}</th><th>${staff?'Applied for':'Market'}</th><th>Stage</th><th>Received</th><th><span class="sr-only">View</span></th></tr></thead><tbody>${applications.map(a=>`<tr><td>${staff?`<a class="person-cell" href="${base()}/applications/${a.id}">${avatar(a.name)}<span><strong>${e(a.name)}</strong><small>${e(a.email)}</small></span></a>`:`<a href="/dashboard/applications/${a.id}"><strong>${e(a.job_title)}</strong></a>`}</td><td>${e(staff?a.job_title:a.country)}</td><td>${statusBadge(a.status)}</td><td class="muted">${date(a.created_at,{day:'2-digit',month:'short'})}</td><td><a class="table-link" href="${base()}/applications/${a.id}" aria-label="Review ${e(staff?a.name:a.job_title)}">${icon('diagonal')}</a></td></tr>`).join('')}</tbody></table></div>`}
function interviewList(interviews,limit=3){const rows=interviews.filter(i=>i.status==='Scheduled').slice(0,limit);return rows.length?rows.map(i=>`<div class="interview-item"><div class="calendar-block"><small>${date(i.starts_at,{month:'short',timeZone:i.timezone})}</small><strong>${date(i.starts_at,{day:'2-digit',timeZone:i.timezone})}</strong></div><div><h4>${e(isStaff()?i.candidate_name:i.job_title)}</h4><p>${e(isStaff()?i.job_title:i.location)}</p><span class="tag">${date(i.starts_at,{hour:'2-digit',minute:'2-digit',timeZone:i.timezone})} · ${i.duration} min · ${e(i.timezone)}</span></div></div>`).join(''):'<p class="fine">No upcoming interviews. New invitations will appear here.</p>'}
async function overviewPage(){const staff=isStaff();const [apps,iv]=await Promise.all([api('/applications'),api('/interviews')]);let content;if(staff){const overview=await api('/staff/overview');const s=overview.stats;const buckets=Array.from({length:14},(_,i)=>{const d=new Date(Date.now()-(13-i)*86400000).toISOString().slice(0,10);return {day:d,count:overview.trend.find(x=>x.day===d)?.count||0}});const max=Math.max(...buckets.map(b=>b.count),1);content=`${heading('YOUR RECRUITMENT, CONSIDERED',`Welcome back, ${e(state.user.name.split(' ')[0])}.`,'A clear view of your people, your pipeline and what comes next.',`<span class="date-chip">${icon('calendar')} ${date(new Date())}</span><a class="btn gold small" href="/workspace/jobs/new">${icon('plus')} Create a role</a>`)}<div class="stats">${statCard('Active opportunities',s.jobs,'Open for new possibilities','briefcase',true)}${statCard('Total applications',s.applications,'People taking their next step','people')}${statCard('On the shortlist',s.shortlisted,'Ready for a closer conversation','bookmark')}${statCard('Upcoming interviews',s.interviews,'Connections in the making','calendar')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h3>Applications at a glance</h3><p>New introductions over the last 14 days</p></div><span class="tag">Last 14 days</span></div><div class="chart" role="img" aria-label="${e(buckets.map(b=>`${b.day}: ${b.count} applications`).join('; '))}">${buckets.map(b=>`<div class="chart-bar" style="height:${Math.max(2,b.count/max*100)}%" title="${b.day}: ${b.count} applications"></div>`).join('')}</div><div class="chart-axis"><span>${date(buckets[0].day,{day:'2-digit',month:'short'})}</span><span class="chart-legend">Applications received</span><span>${date(buckets[13].day,{day:'2-digit',month:'short'})}</span></div></section><section class="panel"><div class="panel-header"><div><h3>Your hiring pipeline</h3><p>Every stage, at a glance</p></div>${icon('people')}</div><div class="pipeline-list">${['Applied','Reviewing','Shortlisted','Interview','Offer','Hired'].map(stage=>{const n=overview.pipeline.find(p=>p.status===stage)?.count||0;return `<a class="pipeline-row" href="/workspace/applications?stage=${encodeURIComponent(stage)}"><span>${stage}</span><div class="pipeline-track"><span style="width:${s.applications?n/s.applications*100:0}%"></span></div><strong>${n}</strong></a>`}).join('')}</div></section></div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h3>Recent applications</h3><a href="/workspace/applications">View all ${icon('arrow')}</a></div>${appTable(apps.applications.slice(0,5))}</section><section class="panel"><div class="panel-header"><h3>On the calendar</h3><a href="/workspace/interviews">View all ${icon('arrow')}</a></div>${interviewList(iv.interviews)}<div class="review-section"><div class="panel-header" style="margin-bottom:8px"><h3>Recent activity</h3></div>${overview.activity.slice(0,3).map(a=>`<div class="activity-item"><span class="activity-dot"></span><div><p>${e(a.action)}</p><small>${e(a.name||'System')} · ${date(a.created_at,{day:'2-digit',month:'short'})}</small></div></div>`).join('')||'<p class="fine">Your team’s activity will appear here.</p>'}</div></section></div>`;}else{const docs=await api('/documents');const active=apps.applications.filter(a=>!['Withdrawn','Declined','Hired'].includes(a.status)).length;content=`${heading('YOUR NEXT CHAPTER',`Hello, ${e(state.user.name.split(' ')[0])}.`,'Manage your applications and upcoming interviews.',`<a class="btn gold small" href="/jobs">Explore opportunities ${icon('arrow')}</a>`)}${candidateNextSteps(docs.documents.length,apps.applications.length)}<div class="stats">${statCard('My applications',apps.applications.length,'Every introduction in one place','file',true)}${statCard('Active applications',active,'Applications moving forward','activity')}${statCard('Saved opportunities',state.saved.size,'Roles you want to revisit','bookmark')}${statCard('Upcoming interviews',iv.interviews.filter(i=>i.status==='Scheduled'&&new Date(i.starts_at)>new Date()).length,'Your next conversations','calendar')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><h3>Your recent applications</h3><a href="/dashboard/applications">View all ${icon('arrow')}</a></div>${appTable(apps.applications.slice(0,5),false)}</section><section class="panel"><div class="panel-header"><h3>Your next conversations</h3></div>${interviewList(iv.interviews)}<div class="review-section"><h3>Your profile</h3><p class="fine">Keep your skills and experience up to date.</p><a class="mini-link" href="/dashboard/profile">Update your profile ${icon('arrow')}</a></div></section></div>`}return workspaceShell(content,'Overview')}
async function applicationsPage(){const {applications}=await api('/applications');state.data.applications=applications;const jobOptions=new Map(applications.map(a=>[a.job_id,a.job_title]));if(isStaff()){const {jobs}=await api('/staff/jobs');jobs.forEach(j=>jobOptions.set(j.id,j.title));}const requestedJob=new URLSearchParams(location.search).get('job');if(requestedJob&&!jobOptions.has(Number(requestedJob)))jobOptions.set(requestedJob,'Selected opportunity (unavailable)');return workspaceShell(`${heading(isStaff()?'THE PEOPLE BEHIND THE PIPELINE':'YOUR RECRUITMENT JOURNEY',isStaff()?'Applications.':'My applications.',isStaff()?'Review candidates and manage hiring stages.':'Track progress and messages from hiring teams.')}<div class="toolbar"><input id="application-search" type="search" placeholder="${isStaff()?'Search people or roles':'Search your applications'}" aria-label="Search applications"><select id="application-job" aria-label="Filter by job"><option value="">All jobs</option>${[...jobOptions.entries()].map(([id,title])=>`<option value="${id}">${e(title)}</option>`).join('')}</select><select id="application-stage" aria-label="Filter by stage"><option value="">All stages</option>${stages.map(s=>`<option>${s}</option>`).join('')}</select>${isStaff()?`<div class="view-switch"><button data-action="view" data-view="table" class="${state.view==='table'?'active':''}">Table</button><button data-action="view" data-view="board" class="${state.view==='board'?'active':''}">Pipeline</button></div>`:''}</div><div id="application-results"></div>`,'Applications')}
function filterApplications(){const q=$('#application-search').value.toLowerCase().trim(),stage=$('#application-stage').value,job=$('#application-job').value;const params=new URLSearchParams();if(q)params.set('q',q);if(stage)params.set('stage',stage);if(job)params.set('job',job);if(state.view==='board')params.set('view','board');history.replaceState(history.state,'',location.pathname+(params.size?'?'+params.toString():''));currentPageUrl=location.pathname+location.search;const rows=state.data.applications.filter(a=>(!q||`${a.name||''} ${a.job_title} ${a.email||''}`.toLowerCase().includes(q))&&(!stage||a.status===stage)&&(!job||String(a.job_id)===job));$('#application-results').innerHTML=!rows.length&&(q||stage||job)?empty('No applications match these filters.','Choose another role or clear the filters.',base()+'/applications','Clear filters'):state.view==='board'&&isStaff()?`<div class="kanban">${stages.filter(s=>!stage||s===stage).map(s=>{const items=rows.filter(a=>a.status===s);return `<section class="kanban-column"><div class="kanban-head"><span>${s}</span><small>${items.length}</small></div>${items.map(a=>`<a class="kanban-card" href="${base()}/applications/${a.id}">${avatar(a.name)}<strong>${e(a.name)}</strong><p>${e(a.job_title)}</p><small>${e(a.country)} · ${date(a.created_at,{day:'2-digit',month:'short'})}</small></a>`).join('')||'<p class="fine">No applications at this stage.</p>'}</section>`}).join('')}</div>`:`<div class="panel">${appTable(rows,isStaff())}</div>`;labelResponsiveTables();}
function analysisHTML(a){if(!a)return '<p class="fine">Review the CV yourself, or generate an evidence checklist to help structure your conversation.</p>';return `<div class="notice">${a.mode==='ai'?'AI-assisted evidence summary · Verify against the original CV.':'Local keyword checklist · This is not AI or a suitability score.'}</div><p class="detail-copy">${e(a.summary)}</p>${[['evidence','Evidence to explore'],['gaps','Points to clarify'],['questions','Questions for a conversation']].map(([key,label])=>`<div class="review-section"><h4>${label}</h4><ul>${a[key].map(s=>`<li>${e(s)}</li>`).join('')||'<li>No items identified. Review the original CV.</li>'}</ul></div>`).join('')}<p class="fine">Created ${date(a.created_at)}. The recruiter remains responsible for the decision.</p>`}
async function applicationPage(id){const data=await api('/applications/'+id),a=data.application;state.data.application=a;const staff=isStaff();let parsed=null;try{parsed=JSON.parse(a.analysis)}catch{}const content=`${heading(staff?'A PERSON, NOT JUST A PROFILE':'YOUR APPLICATION',staff?e(a.name):e(a.job_title),`Applied ${date(a.created_at)} · ${e(a.country)}`,`<a class="btn outline small" href="${base()}/applications">← All applications</a>${staff&&!['Withdrawn','Declined','Hired'].includes(a.status)?`<button class="btn gold small" data-action="schedule" data-id="${a.id}">${icon('calendar')} Schedule interview</button>`:''}`)}<div class="profile-split"><aside><div class="panel"><div class="profile-heading">${avatar(a.name)}<div><h2>${e(a.name)}</h2><p>${e(a.headline||'Candidate')}</p></div></div>${statusBadge(a.status)}<div class="facts" style="margin-top:20px"><div><span>Email</span><strong>${e(a.email)}</strong></div><div><span>Location</span><strong>${e(a.candidate_location||'Not specified')}</strong></div><div><span>Received</span><strong>${date(a.created_at)}</strong></div><div><span>Reference</span><strong>BS-${String(a.id).padStart(5,'0')}</strong></div></div>${a.skills?`<div class="profile-skills">${a.skills.split(',').filter(Boolean).map(s=>`<span class="tag">${e(s.trim())}</span>`).join('')}</div>`:''}${a.document_id?`<a class="btn outline full" href="/api/documents/${a.document_id}" download>${icon('download')} Download CV</a><p class="fine" style="margin:12px 0 0">${e(a.document_name)}${a.parse_status==='needs-review'?' · Text extraction unavailable; review manually.':''}</p>`:'<p class="fine">No document is attached.</p>'}</div><div class="application-summary"><div class="eyebrow">THE OPPORTUNITY</div><h3>${e(a.job_title)}</h3><p>${e(a.location)}, ${e(a.country)}</p><span class="tag gold">${money(a)} / ${e(a.period)}</span></div>${staff?`<div class="panel"><h3>Manage this application</h3>${a.status==='Withdrawn'?'<p class="fine">The candidate withdrew this application.</p>':`<form data-form="stage" data-id="${a.id}" class="stage-form">${selectField('Hiring stage','status',stages.filter(s=>s!=='Withdrawn'),a.status)}<button class="btn small" type="submit">Update</button><p class="error-inline" data-error></p></form>`}</div>`:!['Hired','Declined','Withdrawn'].includes(a.status)?`<button class="btn danger small" data-action="withdraw" data-id="${a.id}">Withdraw application</button>`:''}</aside><div><section class="panel"><div class="panel-header"><h3>${staff?'Candidate introduction':'Your introduction'}</h3>${icon('file')}</div><p class="detail-copy">${e(a.cover||'No additional introduction was included.')}</p>${a.bio?`<h3>Professional summary</h3><p class="detail-copy">${e(a.bio)}</p>`:''}<div class="timeline">${['Applied','Reviewing','Shortlisted','Interview','Offer','Hired'].map(s=>`<span class="${a.status===s?'current':''}">${s}</span>`).join('')}</div></section>${staff?`<section class="panel"><div class="panel-header"><div><h3>Considered insights</h3><p>Evidence to support your professional judgement.</p></div>${icon('spark')}</div><div class="heading-actions"><button class="btn outline small" data-action="analyze" data-id="${a.id}" data-mode="checklist">${icon('file')} Evidence checklist</button><button class="btn gold small" data-action="analyze" data-id="${a.id}" data-mode="ai" ${!state.config.aiEnabled||!a.ai_consent?'disabled':''}>${icon('spark')} AI review</button></div><p class="fine" style="margin-top:12px">${!state.config.aiEnabled?'AI provider is not connected. The local checklist is available.':!a.ai_consent?'AI review requires the candidate’s explicit consent.':'This candidate has consented to external AI-assisted review.'}</p><div id="analysis-result" class="review-section">${analysisHTML(parsed)}</div></section><section class="panel"><div class="panel-header"><h3>Recruiter notes</h3><span class="tag">Private to your team</span></div><form data-form="note" data-id="${a.id}"><div class="field"><label for="note">Add a note</label><textarea name="body" id="note" required maxlength="5000" placeholder="Capture a thoughtful observation or next step…"></textarea></div><p class="error-inline" data-error></p><div class="form-actions"><button class="btn small" type="submit">Save note ${icon('plus')}</button></div></form>${data.notes.map(n=>`<div class="note-card"><strong style="font-size:12px">${e(n.author||'Recruiter')}</strong><p>${e(n.body)}</p><small>${date(n.created_at,{dateStyle:'medium',timeStyle:'short'})}</small></div>`).join('')}</section>`:''}${await conversationPanel(id)}<section class="panel"><div class="panel-header"><h3>Interview history</h3></div>${data.interviews.length?data.interviews.map(i=>`<div class="interview-item"><div>${statusBadge(i.status)}<h4 style="margin-top:12px">${date(i.starts_at,{dateStyle:'full',timeStyle:'short',timeZone:i.timezone})}</h4><p>${e(i.timezone)} · ${i.duration} minutes</p><p>${meetingLocation(i.location)}</p>${i.notes?`<p>${e(i.notes)}</p>`:''}</div></div>`).join(''):'<p class="fine">No interviews have been scheduled yet.</p>'}</section></div></div>`;return workspaceShell(content,'Application detail')}

function aboutPage(){return publicShell(`<div class="container page-body"><section class="page-head"><div class="eyebrow">About Blackstone</div><h1>Ambition is personal.<br><em>So is our approach.</em></h1><p>Blackstone UK Recruitment brings people and businesses together through thoughtful conversations, clear communication and a worldwide perspective.</p></section><section class="two-col about-story"><div><div class="eyebrow">The people behind your next chapter</div><h2>A connection.<br>Not just a placement.</h2><p>Every career has a story. Every organisation has a purpose. We take the time to understand both, helping candidates explore their next move and employers describe the people they need.</p><p>From your first introduction to the next conversation, our focus is on making recruitment feel clear, considered and human.</p><a class="text-link" href="/approach">Explore our approach ${icon('arrow')}</a></div><img src="/assets/executive-lounge.png" alt="A welcoming executive lounge with cream interiors and city views" width="1672" height="941"></section><section class="split-features"><article><small>01 / PERSONAL</small><h3>We start by listening.</h3><p>Your experience, priorities and ambitions shape the conversation.</p></article><article><small>02 / REVIEWED</small><h3>A worldwide perspective.</h3><p>Explore roles across countries and territories, with your next step in mind.</p></article><article><small>03 / CONSIDERED</small><h3>People make the decisions.</h3><p>Technology supports the process. Recruiters review experience and lead the conversation.</p></article></section><section class="cta-band"><div><h2>Let’s get to know you.</h2><p>A meaningful connection starts with a conversation.</p></div><a class="btn" href="/contact">Contact our team ${icon('arrow')}</a></section></div>`)}
function operatingHoursSection(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];return `<section class="operating-hours panel" aria-labelledby="operating-hours-title"><div class="operating-hours-intro"><div class="eyebrow">Here for your next chapter</div><h2 id="operating-hours-title">Operating hours.</h2><p>Speak with our team about your next opportunity or your hiring needs.</p><span class="hours-timezone">UK local time · GMT / BST</span><a class="text-link" href="mailto:info@bsukrecruitment.com">Email our team ${icon('arrow')}</a></div><dl class="hours-schedule">${days.map((day,i)=>`<div class="hours-row${i>4?' hours-closed':''}"><dt>${day}</dt><dd>${i<5?'<time datetime="08:30">08:30</time><span aria-hidden="true"> – </span><span class="sr-only"> to </span><time datetime="17:30">17:30</time>':'Closed'}</dd></div>`).join('')}</dl></section>`;}
function contactPage(){return publicShell(`<div class="container page-body"><section class="page-head"><div class="eyebrow">Contact Blackstone</div><h1>Your next chapter.<br><em>Let’s talk about it.</em></h1><p>Looking for your next role, your next hire, or a little guidance? Choose the best way to reach our team.</p></section><section class="contact-cards" aria-label="Contact details"><article class="panel"><div class="eyebrow">Call our team</div><h2>A personal conversation.</h2><a class="contact-address" href="tel:+448000437867">+44 800 043 7867 ${icon('arrow')}</a><p>Call Blackstone to discuss your recruitment enquiry.</p></article><article class="panel"><div class="eyebrow">Write to us</div><h2>Start with an introduction.</h2><a class="contact-address" href="mailto:info@bsukrecruitment.com">info@bsukrecruitment.com ${icon('arrow')}</a><p>Tell us a little about what you’re looking for.</p><div class="contact-team"><a href="mailto:gaz@bsukrecruitment.com">Contact Gaz ${icon('diagonal')}</a><a href="mailto:sam@bsukrecruitment.com">Contact Sam ${icon('diagonal')}</a></div></article></section>${operatingHoursSection()}<section class="split-features"><article><small>FOR CANDIDATES</small><h3>Make your next move.</h3><p>Browse current opportunities or create a profile and securely upload your CV.</p><a class="text-link" href="/jobs">Find a role ${icon('arrow')}</a></article><article><small>FOR EMPLOYERS</small><h3>Build your next team.</h3><p>Create a company account to post jobs and manage applicants, or send our team a hiring enquiry.</p><a class="text-link" href="/employers">Hire with Blackstone ${icon('arrow')}</a></article><article><small>YOUR ACCOUNT</small><h3>Pick up where you left off.</h3><p>Sign in to manage your profile, applications and upcoming conversations.</p><a class="text-link" href="/login">Sign in ${icon('arrow')}</a></article></section></div>`)}

function healthcarePage(){
 const disciplines=[
  ['01','Doctors & medical specialists','Recruitment shaped around clinical disciplines, experience and the needs of each hospital or clinic.','Consultants · Specialists · Medical officers'],
  ['02','IVF & fertility specialists','Supporting fertility services with professionals whose experience aligns with the clinical and laboratory team.','Fertility specialists · Embryologists · Fertility nurses'],
  ['03','Nurses & midwives','Connecting healthcare organisations with nursing professionals across patient care settings and specialist services.','Registered nurses · Specialist nurses · Midwives'],
  ['04','Allied healthcare professionals','Helping organisations build the multidisciplinary teams that support diagnosis, treatment and recovery.','Physiotherapy · Radiography · Laboratory services'],
  ['05','Hospital & clinical leadership','A considered search for people who can lead clinical teams, services and healthcare operations.','Medical directors · Nursing leadership · Hospital management']
 ];
 return publicShell(`<div class="container page-body healthcare-page"><section class="page-head"><div class="eyebrow">Middle East Healthcare</div><h1>Exceptional people.<br><em>Extraordinary care.</em></h1><p>Specialist healthcare recruitment for Saudi Arabia and the wider Middle East.</p><div class="hero-actions"><a class="btn" href="/healthcare-enquiry">Discuss your staffing requirements ${icon('arrow')}</a><a class="text-link" href="/jobs?sector=Healthcare">Explore Healthcare Opportunities ${icon('diagonal')}</a></div></section>
 <section class="healthcare-panel" aria-labelledby="healthcare-focus"><div><div class="eyebrow">Local understanding. International reach.</div><h2 id="healthcare-focus">Healthcare talent.<br>A personal approach.</h2></div><div class="healthcare-details"><p>Blackstone UK Recruitment connects hospitals, clinics and specialist healthcare organisations across the Middle East with UK and international medical professionals.</p><p>We take time to understand each organisation’s requirements and each professional’s experience, priorities and next step.</p></div><p class="healthcare-footnote">Dedicated recruitment support for Saudi Arabia and the GCC</p></section>
 <section class="section" aria-labelledby="healthcare-disciplines"><div class="section-head"><div><div class="eyebrow">Our areas of focus</div><h2 id="healthcare-disciplines">The people behind better care.</h2></div></div><div class="healthcare-specialisms">${disciplines.map(([number,title,copy,roles])=>`<article class="panel healthcare-specialism"><span class="eyebrow">${number} / Healthcare</span><h3>${title}</h3><p>${copy}</p><p class="fine">${roles}</p></article>`).join('')}<aside class="healthcare-specialism healthcare-conversation"><div class="eyebrow">A requirement of your own?</div><h3>Let’s start with your team.</h3><p>Tell us about the people, service and experience you need.</p><a class="text-link" href="/healthcare-enquiry">Discuss your hiring needs ${icon('arrow')}</a></aside></div></section>
 <section aria-labelledby="healthcare-process"><div class="eyebrow">Considered at every step</div><h2 id="healthcare-process">A clear path forward.</h2><div class="split-features"><article><small>01 / UNDERSTAND</small><h3>Start with the brief.</h3><p>Share your clinical requirements, location and hiring priorities, or tell us about your professional experience.</p></article><article><small>02 / CONNECT</small><h3>Make a thoughtful introduction.</h3><p>Explore relevant roles and discuss experience, expectations and the requirements of the hiring organisation.</p></article><article><small>03 / PROGRESS</small><h3>Keep the conversation clear.</h3><p>Apply through the platform, follow application updates and exchange messages with the hiring team.</p></article></div><p class="fine healthcare-eligibility">Professional registration, licensing and work authorisation requirements depend on the role and destination. The hiring organisation and relevant authorities determine eligibility.</p></section>
 <section class="cta-band"><div><div class="eyebrow">Your next chapter in healthcare</div><h2>Let’s make the right connection.</h2><p>For healthcare organisations and professionals considering their next move.</p></div><div class="healthcare-cta"><a class="btn" href="/jobs?sector=Healthcare">Explore healthcare roles ${icon('arrow')}</a><a class="text-link" href="/contact">Speak with our team ${icon('diagonal')}</a></div></section></div>`);
}

function hiringEnquiryForm(healthcare=false){return `<form class="panel" data-form="enquiry"><h3>${healthcare?'Discuss healthcare recruitment':'Prefer recruitment support?'}</h3><p class="fine">Prefer email? ${contactLink()}</p><div class="form-grid">${field('Your name','name','','text','required maxlength="100" autocomplete="name"')}${field('Company','company','','text','required maxlength="150"')}<div class="span-2">${field('Work email','email','','email','required autocomplete="email"')}</div><div class="span-2">${selectField('Hiring country / territory','country',[['','Select a country'],...countryOptions()],'','required')}</div><div class="field span-2"><label for="message">Who are you looking for?</label><textarea id="message" name="message" maxlength="5000" required placeholder="${healthcare?'Clinical roles, specialties, location and hiring timeline…':'The role, your team, and your ideal timeline…'}">${healthcare?'I would like to discuss healthcare recruitment for our organisation.':''}</textarea></div><p class="fine span-2">By submitting, you agree that Blackstone can review your enquiry and contact you about your hiring needs. <a href="/privacy">Privacy notice</a>.</p><p class="error-inline span-2" data-error role="alert"></p><button class="btn span-2" type="submit">Start a conversation ${icon('arrow')}</button></div></form>`;}
function healthcareEnquiryPage(){return publicShell(`<div class="container page-body"><div class="page-head"><div class="eyebrow">Middle East Healthcare</div><h1>Discuss your<br><em>staffing requirements.</em></h1><p>Tell us about your hospital, clinic or healthcare organisation. Our team will review your requirements and contact you.</p></div><div class="two-col"><div>${hiringEnquiryForm(true)}</div><aside class="dark-panel"><div class="eyebrow">A personal conversation</div><h2>The right people.<br>For your team.</h2><p>Share the clinical specialties, location, experience and hiring timeline you have in mind.</p><p>No account is needed to send an enquiry.</p><p>${contactLink()}</p><a class="text-link" href="tel:+448000437867">+44 800 043 7867</a></aside></div></div>`);}
function healthcareInterestLink(){return state.user?'/dashboard/profile?specialism=healthcare':'/register?next='+encodeURIComponent('/dashboard/profile?specialism=healthcare');}
